import { useState, useEffect, useRef, useCallback } from 'react'
import {
  Brain,
  FileText,
  Folder,
  FolderOpen,
  Plus,
  Trash2,
  Save,
  ChevronRight,
} from 'lucide-react'
import type { MemoryNode } from '../lib/api'
import {
  getMemoryTree,
  getMemoryFile,
  updateMemoryFile,
  createMemoryFile,
  deleteMemoryFile,
} from '../lib/api'
import { toast } from '../components/Toast'

// ── Types ──────────────────────────────────────────────────────────────────────

interface Frontmatter {
  type?: string
  [key: string]: unknown
}

// ── Helpers ────────────────────────────────────────────────────────────────────

function parseFrontmatter(content: string): { meta: Frontmatter; body: string } {
  const match = content.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/)
  if (!match) return { meta: {}, body: content }
  const meta: Frontmatter = {}
  for (const line of match[1].split('\n')) {
    const kv = line.match(/^(\w+):\s*(.*)$/)
    if (kv) meta[kv[1]] = kv[2].trim()
  }
  return { meta, body: match[2] }
}

function countChecklist(content: string): number {
  return (content.match(/^- \[/gm) ?? []).length
}

const MEMORY_TYPE_DESCRIPTIONS: Record<string, string> = {
  user: 'Who the user is — tailors future behavior',
  feedback: 'How to approach work — corrections and validations',
  project: 'Ongoing work context — goals, decisions, deadlines',
  reference: 'Pointers to external systems',
}

// ── File Tree ──────────────────────────────────────────────────────────────────

interface TreeNodeProps {
  node: MemoryNode
  selectedPath: string | null
  onSelect: (path: string) => void
  onDelete: (path: string) => void
}

function TreeNode({ node, selectedPath, onSelect, onDelete }: TreeNodeProps) {
  const [open, setOpen] = useState(true)
  const [hovering, setHovering] = useState(false)

  if (node.type === 'dir') {
    return (
      <div>
        <button
          onClick={() => setOpen((o) => !o)}
          className="flex items-center gap-1.5 w-full px-3 py-1.5 text-[13px] text-text-secondary hover:text-text hover:bg-surface-2 rounded-lg transition-colors"
        >
          <ChevronRight
            className={`w-3.5 h-3.5 shrink-0 transition-transform ${open ? 'rotate-90' : ''}`}
          />
          {open ? (
            <FolderOpen className="w-3.5 h-3.5 shrink-0 text-accent" />
          ) : (
            <Folder className="w-3.5 h-3.5 shrink-0 text-text-muted" />
          )}
          <span className="truncate font-medium">{node.name}</span>
        </button>
        {open && node.children && node.children.length > 0 && (
          <div className="ml-4 border-l border-border pl-2 mt-0.5 space-y-0.5">
            {node.children.map((child) => (
              <TreeNode
                key={child.path}
                node={child}
                selectedPath={selectedPath}
                onSelect={onSelect}
                onDelete={onDelete}
              />
            ))}
          </div>
        )}
      </div>
    )
  }

  const isSelected = selectedPath === node.path
  const Icon = node.name === 'MEMORY.md' ? Brain : FileText

  return (
    <div
      className="relative"
      onMouseEnter={() => setHovering(true)}
      onMouseLeave={() => setHovering(false)}
    >
      <button
        onClick={() => onSelect(node.path)}
        className={`flex items-center gap-2 w-full px-3 py-1.5 text-[13px] rounded-lg transition-colors text-left pr-8 ${
          isSelected
            ? 'bg-accent-muted text-accent-hover font-medium'
            : 'text-text-secondary hover:text-text hover:bg-surface-2'
        }`}
      >
        <Icon className="w-3.5 h-3.5 shrink-0" />
        <span className="truncate">{node.name}</span>
      </button>
      {hovering && (
        <button
          onClick={(e) => {
            e.stopPropagation()
            onDelete(node.path)
          }}
          className="absolute right-2 top-1/2 -translate-y-1/2 p-0.5 rounded text-text-muted hover:text-red-500 transition-colors"
          title="Delete file"
        >
          <Trash2 className="w-3.5 h-3.5" />
        </button>
      )}
    </div>
  )
}

// ── Info Sidebar ───────────────────────────────────────────────────────────────

interface InfoSidebarProps {
  filePath: string | null
  content: string
}

function InfoSidebar({ filePath, content }: InfoSidebarProps) {
  if (!filePath) {
    return (
      <div className="p-4">
        <p className="text-text-muted text-[13px]">Select a file to see details.</p>
      </div>
    )
  }

  const fileName = filePath.split('/').pop() ?? filePath
  const isIndex = fileName === 'MEMORY.md'
  const { meta } = parseFrontmatter(content)
  const memType = typeof meta.type === 'string' ? meta.type : undefined
  const checklistCount = isIndex ? countChecklist(content) : 0

  return (
    <div className="p-4 space-y-5">
      <div>
        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted mb-2">
          File
        </p>
        <p className="text-[13px] font-medium text-text break-all">{fileName}</p>
        <p className="text-[12px] text-text-muted mt-1 break-all">{filePath}</p>
      </div>

      {isIndex && (
        <div>
          <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted mb-2">
            Index Stats
          </p>
          <div className="bg-surface-2 rounded-lg p-3">
            <p className="text-[13px] text-text">
              <span className="font-semibold text-accent">{checklistCount}</span> memory entries
            </p>
          </div>
        </div>
      )}

      {memType && MEMORY_TYPE_DESCRIPTIONS[memType] && (
        <div>
          <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted mb-2">
            Memory Type
          </p>
          <div className="bg-surface-2 rounded-lg p-3">
            <p className="text-[12px] font-semibold text-accent capitalize mb-1">{memType}</p>
            <p className="text-[12px] text-text-secondary leading-relaxed">
              {MEMORY_TYPE_DESCRIPTIONS[memType]}
            </p>
          </div>
        </div>
      )}

      <div>
        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted mb-2">
          Memory Types
        </p>
        <div className="space-y-2">
          {Object.entries(MEMORY_TYPE_DESCRIPTIONS).map(([type, desc]) => (
            <div
              key={type}
              className={`rounded-lg p-2.5 ${
                memType === type ? 'bg-accent-muted border border-accent/30' : 'bg-surface-2'
              }`}
            >
              <p className="text-[11px] font-semibold text-text capitalize mb-0.5">{type}</p>
              <p className="text-[11px] text-text-muted leading-relaxed">{desc}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

// ── New File Form ──────────────────────────────────────────────────────────────

interface NewFileFormProps {
  onSubmit: (filePath: string) => Promise<void>
  onCancel: () => void
}

function NewFileForm({ onSubmit, onCancel }: NewFileFormProps) {
  const [value, setValue] = useState('')
  const [creating, setCreating] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    inputRef.current?.focus()
  }, [])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    const trimmed = value.trim()
    if (!trimmed) return
    setCreating(true)
    await onSubmit(trimmed)
    setCreating(false)
  }

  return (
    <form onSubmit={handleSubmit} className="px-3 pb-3">
      <input
        ref={inputRef}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder="e.g. user/new-memory.md"
        className="w-full px-2.5 py-1.5 text-[12px] bg-surface border border-accent/50 rounded-lg text-text placeholder:text-text-muted focus:outline-none focus:border-accent font-mono"
      />
      <div className="flex gap-1.5 mt-1.5">
        <button
          type="submit"
          disabled={creating || !value.trim()}
          className="flex-1 py-1 text-[11px] font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          {creating ? 'Creating...' : 'Create'}
        </button>
        <button
          type="button"
          onClick={onCancel}
          className="flex-1 py-1 text-[11px] font-medium bg-surface-2 text-text-secondary rounded-lg hover:text-text transition-colors"
        >
          Cancel
        </button>
      </div>
    </form>
  )
}

// ── Main Page ──────────────────────────────────────────────────────────────────

export default function Memory() {
  const [tree, setTree] = useState<MemoryNode[]>([])
  const [treeLoading, setTreeLoading] = useState(true)
  const [selectedPath, setSelectedPath] = useState<string | null>(null)
  const [content, setContent] = useState('')
  const [savedContent, setSavedContent] = useState('')
  const [fileLoading, setFileLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [showNewForm, setShowNewForm] = useState(false)

  const dirty = content !== savedContent

  // Load tree
  const loadTree = useCallback(async () => {
    try {
      const data = await getMemoryTree()
      setTree(data)
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to load memory tree')
    } finally {
      setTreeLoading(false)
    }
  }, [])

  useEffect(() => {
    loadTree()
  }, [loadTree])

  // Load file
  const handleSelectFile = useCallback(async (filePath: string) => {
    if (dirty) {
      const confirmed = window.confirm('You have unsaved changes. Discard them?')
      if (!confirmed) return
    }
    setSelectedPath(filePath)
    setFileLoading(true)
    setContent('')
    setSavedContent('')
    try {
      const data = await getMemoryFile(filePath)
      setContent(data.content)
      setSavedContent(data.content)
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to load file')
    } finally {
      setFileLoading(false)
    }
  }, [dirty])

  // Save file
  const handleSave = useCallback(async () => {
    if (!selectedPath || !dirty) return
    setSaving(true)
    try {
      await updateMemoryFile(selectedPath, content)
      setSavedContent(content)
      toast('success', 'Saved')
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to save')
    } finally {
      setSaving(false)
    }
  }, [selectedPath, content, dirty])

  // Cmd+S
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 's') {
        e.preventDefault()
        handleSave()
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [handleSave])

  // Delete file
  const handleDelete = useCallback(async (filePath: string) => {
    const confirmed = window.confirm(`Delete ${filePath}?`)
    if (!confirmed) return
    try {
      await deleteMemoryFile(filePath)
      toast('success', 'Deleted')
      if (selectedPath === filePath) {
        setSelectedPath(null)
        setContent('')
        setSavedContent('')
      }
      loadTree()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to delete')
    }
  }, [selectedPath, loadTree])

  // Create file
  const handleCreateFile = useCallback(async (filePath: string) => {
    try {
      await createMemoryFile(filePath)
      toast('success', 'Created')
      setShowNewForm(false)
      await loadTree()
      handleSelectFile(filePath)
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to create file')
    }
  }, [loadTree, handleSelectFile])

  // Breadcrumb
  const breadcrumbs = selectedPath ? selectedPath.split('/') : []

  return (
    <div className="flex h-screen overflow-hidden">
      {/* Left panel — file tree */}
      <aside className="w-[240px] min-w-[240px] border-r border-border bg-surface flex flex-col h-full">
        <div className="px-4 py-3 border-b border-border flex items-center justify-between shrink-0">
          <div className="flex items-center gap-2">
            <Brain className="w-4 h-4 text-accent" />
            <span className="text-[13px] font-semibold tracking-tight">Memory Brain</span>
          </div>
          <button
            onClick={() => setShowNewForm((v) => !v)}
            title="New file"
            className="p-1 rounded-lg text-text-muted hover:text-accent hover:bg-surface-2 transition-colors"
          >
            <Plus className="w-4 h-4" />
          </button>
        </div>

        {showNewForm && (
          <div className="border-b border-border py-2">
            <NewFileForm onSubmit={handleCreateFile} onCancel={() => setShowNewForm(false)} />
          </div>
        )}

        <div className="flex-1 overflow-y-auto py-2 px-2 space-y-0.5">
          {treeLoading ? (
            <div className="flex items-center justify-center py-8">
              <div className="w-5 h-5 border-2 border-accent border-t-transparent rounded-full animate-spin" />
            </div>
          ) : tree.length === 0 ? (
            <p className="text-text-muted text-[12px] px-3 py-4">No memory files found.</p>
          ) : (
            tree.map((node) => (
              <TreeNode
                key={node.path}
                node={node}
                selectedPath={selectedPath}
                onSelect={handleSelectFile}
                onDelete={handleDelete}
              />
            ))
          )}
        </div>
      </aside>

      {/* Middle panel — editor */}
      <main className="flex-1 min-w-0 flex flex-col h-full bg-surface">
        {/* Editor header */}
        <div className="px-5 py-3 border-b border-border flex items-center justify-between shrink-0">
          <div className="flex items-center gap-1.5 text-[12px] text-text-muted min-w-0">
            {breadcrumbs.length === 0 ? (
              <span className="text-text-muted italic">No file selected</span>
            ) : (
              breadcrumbs.map((crumb, i) => (
                <span key={i} className="flex items-center gap-1.5">
                  {i > 0 && <ChevronRight className="w-3 h-3 shrink-0" />}
                  <span
                    className={
                      i === breadcrumbs.length - 1
                        ? 'text-text font-medium'
                        : 'text-text-muted'
                    }
                  >
                    {crumb}
                  </span>
                </span>
              ))
            )}
          </div>
          <div className="flex items-center gap-2 shrink-0 ml-4">
            {dirty && (
              <span className="w-2 h-2 rounded-full bg-accent shrink-0" title="Unsaved changes" />
            )}
            <button
              onClick={handleSave}
              disabled={!dirty || saving}
              className="flex items-center gap-1.5 px-3 py-1.5 text-[12px] font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              <Save className="w-3.5 h-3.5" />
              {saving ? 'Saving...' : 'Save'}
            </button>
            <span className="text-[11px] text-text-muted hidden sm:block">Cmd+S</span>
          </div>
        </div>

        {/* Textarea */}
        <div className="flex-1 min-h-0 p-4">
          {!selectedPath ? (
            <div className="flex items-center justify-center h-full">
              <div className="text-center space-y-2">
                <Brain className="w-10 h-10 text-text-muted mx-auto" />
                <p className="text-text-secondary text-[14px]">Select a file to edit</p>
                <p className="text-text-muted text-[12px]">
                  Choose a memory file from the left panel
                </p>
              </div>
            </div>
          ) : fileLoading ? (
            <div className="flex items-center justify-center h-full">
              <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
            </div>
          ) : (
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="w-full h-full bg-surface border border-border rounded-xl p-4 font-mono text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors leading-relaxed"
              spellCheck={false}
              placeholder="Start writing..."
            />
          )}
        </div>
      </main>

      {/* Right panel — info sidebar */}
      <aside className="w-[260px] min-w-[260px] border-l border-border bg-surface flex flex-col h-full overflow-y-auto">
        <div className="px-4 py-3 border-b border-border shrink-0">
          <p className="text-[13px] font-semibold tracking-tight">Info</p>
        </div>
        <InfoSidebar filePath={selectedPath} content={content} />
      </aside>
    </div>
  )
}

